Translate("esES", "obsidian-sentinel", {
	title = "Centinela de obsidiana",
	subtitle = "Guardián de cristal negro",
	found = "Una caverna en las profundidades medias de Uldaman",
	hint = [=[Busque al guardián de cristal negro en las cavernas de Uldaman.]=],
	allegiance = "Los Creadores",
	sections = {
		{
			title = "Resumen",
			text = [=[El Centinela de obsidiana es uno de los guardianes de piedra de {link:uldaman}Uldaman{/link}, pero está hecho de cristal oscuro en lugar de piedra. Los hechizos que se lanzan contra él a menudo se vuelven contra quienes los lanzan. Cuando se le golpea, se astilla. Cada astilla se desprende como un fragmento que lucha por su cuenta, y el centinela se debilita a medida que se rompe.]=],
		},
		{
			title = "Importancia",
			text = [=[El corazón del centinela es una fuente de energía tan poderosa que los magos la codician. {link:tabetha}Tabetha{/link}, una maga que vive sola en el {link:dustwallow-marsh}Marjal Revolcafango{/link}, ha enviado a personas de su confianza a tomarlo. Sus colegas la llamaron loca por pedirlo.]=],
		},
		{ title = "Hazañas", text = "• Guarda una caverna de {link:uldaman}Uldaman{/link}." },
	},
	chapters = {
		{
			title = "Energía en Uldaman",
			hint = [=[Responda a la maga de Revolcafango que necesita una fuente de energía.]=],
			text = [=[{link:tabetha}Tabetha{/link} necesitaba una fuente de energía, y las mejores, decía, eran las más antiguas y las más difíciles de conseguir. Nombró al Centinela de obsidiana. Cuando le llevaron su fuente, quedó encantada, y más encantada aún de que sus colegas escépticos hubieran quedado en evidencia.]=],
		},
	},
	bonds = {
		{ id = "tabetha", name = "Tabetha", note = "buscó su corazón" },
	},
})

