Translate("esES", "remains-of-a-paladin", {
	title = "Restos de un paladín",
	subtitle = "Un paladín muerto en Uldaman",
	found = "La gran sala de templo cerca de la entrada de Uldaman",
	hint = [=[Busque los restos de un caballero humano en las salas de Uldaman.]=],
	allegiance = "Desconocida",
	aliases = { "el paladín caído de Uldaman" },
	sections = {
		{
			title = "Resumen",
			text = [=[En un pasillo de la gran sala de templo de {link:uldaman}Uldaman{/link} yacen los restos de un paladín humano. Vino a las {link:badlands}Tierras Inhóspitas{/link} en una misión elegida por él mismo, para purgar una mácula maligna que creía extendida sobre la excavación. Llevaba un fino collar mágico que le hizo Talvash del Kissel, un joyero {link:gnomes}gnomo{/link} de {link:ironforge}Forjaz{/link}. Murió en la cámara, y su collar se rompió y sus gemas se dispersaron. Su diario manchado de sangre, escrito en la lengua de los humanos, yace a su lado.]=],
		},
		{
			title = "Importancia",
			text = [=[La muerte del paladín proyectó una larga sombra. Un rival de Talvash hizo correr el rumor de que el collar había maldecido a su portador, y el negocio del joyero se arruinó. En la {link:horde}Horda{/link}, los chatarreros de Droffers e Hijo también oyeron hablar del collar, y lo quisieron.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ningún registro da el nombre del paladín, su orden o su hogar. Qué era la mácula maligna, y si la encontró, no se sabe.]=],
		},
	},
	chapters = {
		{
			title = "El diario del paladín",
			hint = "Busque al paladín muerto en las salas de Uldaman.",
			text = [=[El diario fue la última obra del paladín. Había averiguado adónde había ido cada gema. Los enanos Shadowforge habían escondido el rubí en sus barricadas mientras luchaban contra los troggs por la cámara. Los troggs habían puesto el topacio en una urna cerca de un campamento de enanos de {link:ironforge}Forjaz{/link}. El cacique {link:troggs}trogg{/link} se había quedado el zafiro. Del lado de la {link:horde}Horda{/link}, el diario no pudo leerse hasta que el trol {link:jarkal-mossmeld}Jarkal Mossmeld{/link} de {link:kargath}Kargath{/link} lo tradujo, a cambio de la oportunidad de estudiar él mismo el collar.]=],
		},
	},
	mentions = {
		{ text = "El collar roto" },
		{ text = "Saber a cambio de un precio" },
		{ text = "Recuperación del collar" },
		{ text = "Restaurar el collar" },
	},
	bonds = {
		{ id = "grimlok", name = "Grimlok", note = "se quedó su zafiro" },
		{ id = "galgann-firehammer", name = "Galgann Firehammer", note = "su gente se quedó su rubí" },
	},
})

Translate("esES", "annora", {
