	found = "Una cueva llena de escórpidos, junto a las salas de Uldaman",
	hint = [=[Limpie la cueva de escórpidos de Uldaman, y vea quién se ha estado escondiendo allí.]=],
	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[Annora es una encantadora humana, maestra en su arte, que se esconde en una cueva de {link:uldaman}Uldaman{/link} infestada de escórpidos. Solo sale cuando las criaturas han desaparecido, y da las gracias a sus rescatadores con sentimiento: había empezado a temer que tendría que esconderse allí para siempre. Comparte su oficio con quienes se lo han ganado.]=],
		},
		{
			title = "Importancia",
			text = [=[Annora es uno de los pocos rostros amigos en las profundidades de {link:uldaman}Uldaman{/link}. Que una maestra de su oficio se encuentre escondida entre sus escórpidos es uno de los relatos más extraños de la cámara.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ningún registro dice quién es Annora, dónde aprendió su arte ni qué la trajo a {link:uldaman}Uldaman{/link}.]=],
		},
	},
})
